import { useEffect, useState } from 'react';
import { motion } from 'motion/react';

const navLinks = [
  { label: 'About', href: '#about' },
  { label: 'Work', href: '#work' },
  { label: 'Contact', href: '#contact' },
];

export default function Header() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 60);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled
          ? 'bg-background/95 backdrop-blur-sm border-b border-border/20'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-12 flex items-center justify-between h-20">
        {/* Monogram Logo */}
        <a href="/" aria-label="Home" className="flex items-center">
          <img
            src="/airo-assets/images/logo/primary"
            alt="AJ logo"
            className="h-10 w-auto object-contain shrink-0"
          />
        </a>

        {/* Nav */}
        <nav className="flex items-center gap-8" aria-label="Main navigation">
          {navLinks.map((link) => (
            <a
              key={link.href}
              href={link.href}
              className="relative text-sm tracking-widest uppercase text-foreground/70 hover:text-foreground transition-colors duration-200 group"
            >
              {link.label}
              <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
            </a>
          ))}
        </nav>
      </div>
    </header>
  );
}

export default function Footer() {
  const year = new Date().getFullYear();

  const scrollToTop = (e: React.MouseEvent) => {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <footer className="border-t border-border/20 bg-background">
      <div className="max-w-7xl mx-auto px-6 md:px-12 py-8 flex items-center justify-between">
        <p className="text-xs tracking-widest uppercase text-muted-foreground">
          &copy; {year} Alex Johnson. All rights reserved.
        </p>
        <a
          href="#top"
          onClick={scrollToTop}
          className="text-xs tracking-widest uppercase text-muted-foreground hover:text-primary transition-colors duration-200"
        >
          Back to top ↑
        </a>
      </div>
    </footer>
  );
}

