import { Helmet } from '@dr.pogodin/react-helmet';
import { motion, useScroll, useTransform } from 'motion/react';
import { useRef } from 'react';
import { Github, Linkedin, Twitter, Mail, ArrowDown } from 'lucide-react';

// ─── Accent line that draws in ───────────────────────────────────────────────
function AccentLine({ className = '' }: { className?: string }) {
  return (
    <motion.div
      className={`h-px bg-primary ${className}`}
      initial={{ scaleX: 0, originX: 0 }}
      animate={{ scaleX: 1 }}
      transition={{ duration: 0.8, delay: 0.9, ease: 'easeOut' as const }}
      style={{ transformOrigin: 'left center' }}
    />
  );
}

// ─── Section fade-in wrapper ──────────────────────────────────────────────────
function FadeIn({
  children,
  delay = 0,
  className = '',
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  return (
    <motion.div
      className={className}
      initial={{ opacity: 0, y: 28 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay, ease: 'easeOut' as const }}
    >
      {children}
    </motion.div>
  );
}

// ─── Skill tag ────────────────────────────────────────────────────────────────
function SkillTag({ label }: { label: string }) {
  return (
    <span className="inline-block px-3 py-1 text-xs tracking-widest uppercase border border-border/40 text-muted-foreground">
      {label}
    </span>
  );
}

// ─── Social icon link ─────────────────────────────────────────────────────────
function SocialLink({
  href,
  label,
  children,
}: {
  href: string;
  label: string;
  children: React.ReactNode;
}) {
  return (
    <motion.a
      href={href}
      aria-label={label}
      target="_blank"
      rel="noopener noreferrer"
      className="text-muted-foreground hover:text-primary transition-colors duration-200"
      whileHover={{ scale: 1.1 }}
      transition={{ duration: 0.15 }}
    >
      {children}
    </motion.a>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────
export default function HomePage() {
  const heroRef = useRef<HTMLElement>(null);
  const { scrollYProgress } = useScroll({
    target: heroRef,
    offset: ['start start', 'end start'],
  });
  const heroOpacity = useTransform(scrollYProgress, [0, 0.6], [1, 0]);

  return (
    <>
      <Helmet>
        <title>Alex Johnson — Designer & Developer</title>
        <meta
          name="description"
          content="Personal portfolio of Alex Johnson — a designer and developer crafting thoughtful digital experiences."
        />
      </Helmet>

      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <motion.section
        ref={heroRef}
        id="top"
        className="relative min-h-screen flex flex-col justify-center px-6 md:px-12 pt-20"
        style={{ opacity: heroOpacity }}
      >
        {/* Sparse dot accent top-right */}
        <div className="absolute top-32 right-12 hidden md:flex flex-col gap-2 opacity-30">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="w-1 h-1 rounded-full bg-primary" />
          ))}
        </div>

        <div className="max-w-7xl mx-auto w-full">
          {/* Eyebrow */}
          <motion.p
            className="text-xs tracking-[0.3em] uppercase text-primary mb-6"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5, delay: 0.2, ease: 'easeOut' as const }}
          >
            Portfolio
          </motion.p>

          {/* Name */}
          <motion.h1
            className="font-heading font-bold leading-[0.9] text-foreground mb-4"
            style={{
              fontSize: 'clamp(4rem, 10vw, 10rem)',
              letterSpacing: '-0.02em',
            }}
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: 'easeOut' as const }}
          >
            Alex
            <br />
            Johnson.
          </motion.h1>

          {/* Accent line under name */}
          <AccentLine className="w-24 mb-8" />

          {/* Tagline */}
          <motion.p
            className="text-lg md:text-xl text-muted-foreground max-w-md leading-relaxed ml-1"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.7, ease: 'easeOut' as const }}
          >
            Designer & developer crafting{' '}
            <em className="text-foreground not-italic">thoughtful digital experiences</em> that
            balance form and function.
          </motion.p>
        </div>

        {/* Scroll indicator */}
        <motion.div
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-muted-foreground"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5, delay: 1.2 }}
        >
          <span className="text-xs tracking-widest uppercase">Scroll</span>
          <motion.div
            animate={{ y: [0, 6, 0] }}
            transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' as const }}
          >
            <ArrowDown size={14} className="text-primary" />
          </motion.div>
        </motion.div>
      </motion.section>

      {/* ── ABOUT ────────────────────────────────────────────────────────── */}
      <section id="about" className="py-32 px-6 md:px-12">
        <div className="max-w-7xl mx-auto">
          <FadeIn>
            <div className="flex items-center gap-4 mb-16">
              <p className="text-xs tracking-[0.3em] uppercase text-primary">01</p>
              <div className="h-px w-8 bg-primary" />
              <h2 className="text-xs tracking-[0.3em] uppercase text-muted-foreground">About</h2>
            </div>
          </FadeIn>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-24 items-start">
            {/* Text column */}
            <div>
              <FadeIn delay={0.1}>
                <h3
                  className="font-heading font-bold text-foreground leading-tight mb-8"
                  style={{ fontSize: 'clamp(2rem, 4vw, 3.5rem)' }}
                >
                  Crafting with
                  <br />
                  <span className="text-primary">intention.</span>
                </h3>
              </FadeIn>

              <FadeIn delay={0.2}>
                <p className="text-muted-foreground leading-relaxed mb-6">
                  I'm a multidisciplinary designer and front-end developer with over 8 years of
                  experience building products for startups and established brands. I believe great
                  design is invisible — it solves problems so elegantly that users never notice the
                  craft behind it.
                </p>
                <p className="text-muted-foreground leading-relaxed mb-10">
                  My work lives at the intersection of visual design and engineering. I care deeply
                  about typography, motion, and the small details that make an interface feel alive.
                </p>
              </FadeIn>

              {/* Skills */}
              <FadeIn delay={0.3}>
                <p className="text-xs tracking-widest uppercase text-muted-foreground mb-4">
                  Disciplines
                </p>
                <div className="flex flex-wrap gap-2">
                  {[
                    'UI Design',
                    'Front-End Dev',
                    'Motion',
                    'Branding',
                    'React / TypeScript',
                    'Figma',
                  ].map((skill) => (
                    <SkillTag key={skill} label={skill} />
                  ))}
                </div>
              </FadeIn>
            </div>

            {/* Image column */}
            <FadeIn delay={0.2} className="relative">
              <div className="relative aspect-square overflow-hidden">
                <img
                  src="/airo-assets/images/pages/home/avatar"
                  alt="Alex Johnson"
                  className="w-full h-full object-cover grayscale"
                />
                {/* Amber overlay tint */}
                <div className="absolute inset-0 bg-primary/10 mix-blend-multiply" />
              </div>
              {/* Decorative offset border */}
              <div className="absolute -bottom-4 -right-4 w-full h-full border border-primary/30 -z-10" />
            </FadeIn>
          </div>
        </div>
      </section>

      {/* Divider */}
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className="h-px bg-border/20" />
      </div>

      {/* ── CONTACT ──────────────────────────────────────────────────────── */}
      <section id="contact" className="py-32 px-6 md:px-12">
        <div className="max-w-7xl mx-auto">
          <FadeIn>
            <div className="flex items-center gap-4 mb-16">
              <p className="text-xs tracking-[0.3em] uppercase text-primary">02</p>
              <div className="h-px w-8 bg-primary" />
              <h2 className="text-xs tracking-[0.3em] uppercase text-muted-foreground">Contact</h2>
            </div>
          </FadeIn>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-16 items-end">
            {/* Left — copy + email */}
            <div>
              <FadeIn delay={0.1}>
                <h3
                  className="font-heading font-bold text-foreground leading-tight mb-6"
                  style={{ fontSize: 'clamp(2rem, 4vw, 3.5rem)' }}
                >
                  Let's make
                  <br />
                  something{' '}
                  <span className="text-primary">great.</span>
                </h3>
              </FadeIn>

              <FadeIn delay={0.2}>
                <p className="text-muted-foreground leading-relaxed mb-10 max-w-sm">
                  I'm open to freelance projects, full-time roles, and interesting collaborations.
                  Drop me a line — I'd love to hear what you're working on.
                </p>
              </FadeIn>

              <FadeIn delay={0.3}>
                <a
                  href="mailto:hello@alexjohnson.co"
                  className="group inline-flex items-center gap-3 text-foreground hover:text-primary transition-colors duration-200"
                >
                  <Mail size={18} className="text-primary shrink-0" />
                  <span
                    className="font-heading font-semibold relative"
                    style={{ fontSize: 'clamp(1.1rem, 2.5vw, 1.6rem)' }}
                  >
                    hello@alexjohnson.co
                    <span className="absolute -bottom-1 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
                  </span>
                </a>
              </FadeIn>
            </div>

            {/* Right — social icons */}
            <FadeIn delay={0.2} className="flex flex-col gap-8 md:items-end">
              <p className="text-xs tracking-widest uppercase text-muted-foreground">
                Find me online
              </p>
              <div className="flex items-center gap-6">
                <SocialLink href="https://github.com" label="GitHub">
                  <Github size={22} />
                </SocialLink>
                <SocialLink href="https://linkedin.com" label="LinkedIn">
                  <Linkedin size={22} />
                </SocialLink>
                <SocialLink href="https://twitter.com" label="Twitter / X">
                  <Twitter size={22} />
                </SocialLink>
              </div>
            </FadeIn>
          </div>
        </div>
      </section>
    </>
  );
}

