import { motion } from 'motion/react';
import { ArrowUpRight } from 'lucide-react';

export interface Project {
  index: string;
  title: string;
  description: string;
  tags: string[];
  imageSlot: string;
  href?: string;
}

export default function ProjectCard({ project, delay = 0 }: { project: Project; delay?: number }) {
  return (
    <motion.article
      initial={{ opacity: 0, y: 32 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay, ease: 'easeOut' as const }}
      className="group relative flex flex-col"
    >
      {/* Image */}
      <div className="relative overflow-hidden aspect-[16/10] mb-6">
        <img
          src={project.imageSlot}
          alt={project.title}
          className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700 scale-100 group-hover:scale-105"
        />
        {/* Amber tint overlay */}
        <div className="absolute inset-0 bg-primary/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500 mix-blend-multiply" />
        {/* Dark gradient at bottom */}
        <div className="absolute inset-0 bg-gradient-to-t from-background/60 to-transparent" />
      </div>

      {/* Meta */}
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1">
          {/* Index + title row */}
          <div className="flex items-baseline gap-3 mb-2">
            <span className="text-xs text-primary tracking-widest">{project.index}</span>
            <h3 className="font-heading font-semibold text-foreground text-xl leading-tight">
              {project.title}
            </h3>
          </div>

          <p className="text-sm text-muted-foreground leading-relaxed mb-4">
            {project.description}
          </p>

          {/* Tags */}
          <div className="flex flex-wrap gap-2">
            {project.tags.map((tag) => (
              <span
                key={tag}
                className="text-xs tracking-widest uppercase text-muted-foreground border border-border/30 px-2 py-0.5"
              >
                {tag}
              </span>
            ))}
          </div>
        </div>

        {/* Arrow link */}
        {project.href && (
          <a
            href={project.href}
            aria-label={`View ${project.title}`}
            className="shrink-0 mt-1 w-9 h-9 border border-border/40 flex items-center justify-center text-muted-foreground hover:border-primary hover:text-primary transition-colors duration-200"
          >
            <ArrowUpRight size={16} />
          </a>
        )}
      </div>

      {/* Bottom accent line — draws in on hover */}
      <div className="mt-6 h-px bg-border/20 relative overflow-hidden">
        <motion.div
          className="absolute inset-y-0 left-0 bg-primary"
          initial={{ width: 0 }}
          whileInView={{ width: '2rem' }}
          viewport={{ once: true }}
          transition={{ duration: 0.5, delay: delay + 0.3, ease: 'easeOut' as const }}
        />
      </div>
    </motion.article>
  );
}

